// Lista pipeline'ów do uruchomienia w jednym przebiegu.
return [
  { json: { pipeline: 'cs2_demo' } },
  { json: { pipeline: 'ecommerce_demo' } }
];

// Formatowanie odpowiedzi API do czytelnego raportu (Markdown) + flagi.
const badge = { LIVE_DATA: '🟢', MOCK_DATA: '🟡', BLOCKED_MISSING_SECRET: '🔴' };
const out = [];
for (const item of $input.all()) {
  const r = item.json;
  const m = r.metrics || {};
  const lines = [
    `### ${badge[r.data_status] || '⚪'} ${r.pipeline} — ${r.run_status} / ${r.data_status}`,
    `run_id: \`${r.run_id}\` · records: ${r.records_processed} · ${r.execution_time_sec}s`,
    `report: ${r.report_path || 'n/a'}`,
  ];
  if (r.pipeline === 'cs2_demo') {
    lines.push(`WR ${m.win_rate}% · K/D ${m.kd_ratio} · rating ${m.avg_rating} · ADR ${m.avg_adr} · form ${m.form_score}/100 (${m.form_trend})`);
  } else if (r.pipeline === 'ecommerce_demo') {
    lines.push(`revenue ${m.revenue_total} · profit ${m.profit_total} · margin ${m.margin_pct}% · loss orders ${m.loss_orders_count} (${m.loss_orders_total})`);
    if (m.wow) {
      const w = m.wow;
      const arrow = (v) => v === null || v === undefined ? 'n/d' : (v > 0 ? '▲' : v < 0 ? '▼' : '=') + ' ' + v + '%';
      lines.push(`WoW ${w.week} vs ${w.prev_week}: revenue ${arrow(w.revenue_delta_pct)} · profit ${arrow(w.profit_delta_pct)} · margin ${w.margin_prev}% → ${w.margin_pct}% (${w.margin_delta_pp} pp) · orders ${w.orders_prev} → ${w.orders}${w.partial_week ? ' · ⚠ partial week' : ''}`);
    }
  }
  if (r.error) lines.push(`ERROR: ${r.error}`);
  out.push({ json: {
    pipeline: r.pipeline,
    run_id: r.run_id,
    run_status: r.run_status,
    data_status: r.data_status,
    is_mock: r.data_status !== 'LIVE_DATA',
    // alert: run nieudany, brak danych, albo tydzień-do-tygodnia: przychód spadł ≥15% (pełny tydzień) lub marża spadła ≥3 pp
    needs_attention: r.run_status !== 'SUCCESS' || r.data_status === 'BLOCKED_MISSING_SECRET'
      || (m.wow && !m.wow.partial_week && m.wow.revenue_delta_pct !== null && m.wow.revenue_delta_pct <= -15)
      || (m.wow && m.wow.margin_delta_pp <= -3),
    wow: m.wow || null,
    records_processed: r.records_processed,
    report_path: r.report_path,
    summary_markdown: lines.join('\n'),
    metrics: m,
  }});
}
return out;

// Gałąź alertowa: tu podepnij Discord/Slack/Email node.
// Domyślnie tylko oznacza item jako ALERT (żeby workflow działał bez credentiali).
return $input.all().map(i => ({ json: { ...i.json, alert: true, alert_text: `⚠️ DaaS ALERT\n${i.json.summary_markdown}` } }));

// Gałąź OK: agregacja podsumowań w jeden digest.
const items = $input.all();
const digest = items.map(i => i.json.summary_markdown).join('

');
return [{ json: { ok: true, pipelines: items.length, digest_markdown: `## DaaS weekly digest

${digest}` } }];
